export function Viewport({
  url = "{{url}}",
  device = "{{device}}",
  accent = "{{accent}}",
  addressBar = {{addressBar}},
}) {
  const maxWidth = device === "mobile" ? 200 : 420;
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430", background: "#FAF7F2", padding: 16, display: "flex", justifyContent: "center" }}>
      <div style={{ width: "100%", maxWidth, borderRadius: 10, overflow: "hidden", boxShadow: "0 10px 24px rgba(36,20,48,.18)", background: "#fff" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", background: accent }}>
          <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#FAF7F255" }} />
          <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#FAF7F255" }} />
          <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#FAF7F255" }} />
          {addressBar && <span style={{ marginLeft: 8, background: "#FAF7F222", color: "#FAF7F2", borderRadius: 4, padding: "2px 8px", fontSize: 11, flex: 1 }}>{url}</span>}
        </div>
        <div style={{ height: 110, display: "flex", alignItems: "center", justifyContent: "center", color: "#24143066", backgroundImage: "repeating-linear-gradient(45deg, #24143006 0 8px, transparent 8px 16px)" }}>Visible viewport area</div>
      </div>
    </div>
  );
}
